// q4_template.js - Template engine that replaces {{name}} with data[name]

function render(template, data) {
    // Replace all {{ name }} patterns with corresponding data values
    return template.replace(/\{\{\s*([^}]+?)\s*\}\}/g, (match, key) => {
        return data[key] !== undefined ? data[key] : '';
    });
}

// Export the function
module.exports = { render };
```

