// Test 5: No matches
const template5 = "Hello World!";
const data5 = { name: "John" };
const result5 = render(template5, data5);
assert.strictEqual(result5, "Hello World!");

// Test 6: Empty data
const template6 = "Hello {{ name }}!";
const data6 = {};
const result6 = render(template6, data6);
assert.strictEqual(result6, "Hello !");

console.log("All asserts passed!");
